/**
 * B3.12 actual engine→Python signature→TypeScript verification→disposable D1/R2.
 *
 * No Worker route or hosted R2 exists here. The fixture is generated by
 * real_clamd_acceptance.py ONLY when a genuine ClamAV daemon passed EICAR.
 * No user content, production credentials, screenshots, or CI uploads.
 *
 * Default portal Vitest skips this explicitly, not a false PASS. The dedicated
 * real-AV workflow MUST set IAICT_B312_REAL_AV_BRIDGE_FIXTURE and invoke this file.
 */
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { readFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { Miniflare, convertV4MiniflareOptions } from "miniflare";
import { storePrivateMediaScanEvidence } from "../../lib/media-r2-scan-evidence";
import { verifyMediaScanClaim, type SignedScanClaim } from "../../lib/media-scan-attestation";
import { cleanupExpiredPrivateMedia } from "../../lib/media-r2-cleanup";
import type { D1DatabaseLike } from "../../lib/cloudflare-db";
import type { MediaR2BucketLike } from "../../lib/media-r2-runtime";
import { MEDIA_POLICY } from "../../lib/media-policy";

const TEST_SECRET = new TextEncoder().encode("ci-real-clamav-isolated-nonproduction");
const environmentFixture = process.env.IAICT_B312_REAL_AV_BRIDGE_FIXTURE;

type Fixture = {
  version: number;
  source_b64: string;
  derivative_b64: string;
  receipt: SignedScanClaim;
};

const sha = async (data: Uint8Array): Promise<string> => {
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", new Uint8Array(data)));
  return [...digest].map(n => n.toString(16).padStart(2, "0")).join("");
};

function decodeLimited(data: string, bytes: number): Uint8Array {
  if (typeof data !== "string" || data.length > bytes * 2 || !/^[A-Za-z0-9+/]+={0,2}$/.test(data)) {
    throw Error("INVALID_CI_SYNTHETIC_FIXTURE");
  }
  const out = new Uint8Array(Buffer.from(data, "base64"));
  if (out.length < 12 || out.length > bytes) throw Error("INVALID_CI_SYNTHETIC_BYTES");
  return out;
}

(environmentFixture ? describe : describe.skip)(
  "B3.12 real ClamAV → real Pillow → signed private D1/R2 CAS (CI fixture ONLY)", () => {
    let mf: Miniflare;
    let db: D1DatabaseLike;
    let bucket: MediaR2BucketLike;
    let source: Uint8Array;
    let derivative: Uint8Array;
    let signed: SignedScanClaim;
    let sourceKey: string;

    beforeAll(async () => {
      if (!environmentFixture) throw Error("REAL_AV_FIXTURE_NOT_CONFIGURED");
      const raw = await readFile(environmentFixture, "utf8");
      if (Buffer.byteLength(raw, "utf8") > 32 * 1024 * 1024) throw Error("OVERSIZED_CI_FIXTURE");
      const f = JSON.parse(raw) as Fixture;
      if (f.version !== 1 || !f.receipt?.claim) throw Error("INVALID_CI_FIXTURE");
      source = decodeLimited(f.source_b64, MEDIA_POLICY.file.maxBytes);
      derivative = decodeLimited(f.derivative_b64, MEDIA_POLICY.file.maxBytes);
      signed = f.receipt;
      expect(source.slice(0, 8)).toEqual(new Uint8Array([137,80,78,71,13,10,26,10]));
      expect(new TextDecoder().decode(derivative.slice(0, 4))).toBe("RIFF");
      expect(await sha(source)).toBe(signed.claim.sourceSha256);
      expect(await sha(derivative)).toBe(signed.claim.derivativeSha256);
      expect(derivative.byteLength).toBe(signed.claim.derivativeSize);

      mf = new Miniflare(convertV4MiniflareOptions({
        modules: true,
        script: "export default {fetch(){return new Response('isolated-fixture')}}",
        compatibilityDate: "2026-10-12",
        compatibilityFlags: ["nodejs_compat"],
        d1Databases: {DB: randomUUID()},
        r2Buckets: {MEDIA_BUCKET: "qa-b312-real-av-only"},
      }));
      db = await mf.getD1Database("DB") as unknown as D1DatabaseLike;
      bucket = await mf.getR2Bucket("MEDIA_BUCKET") as unknown as MediaR2BucketLike;
      for (const name of [
        "0001_core.sql",
        "0025_media_r2_quarantine.sql",
        "0026_media_r2_scan_evidence.sql",
      ]) {
        const sql = await readFile(new URL("../../cloudflare/migrations/" + name, import.meta.url), "utf8");
        for (const statement of sql.split(/;\s*(?:\r?\n|$)/).map(s => s.trim())
          .filter(s => s.split(/\r?\n/).some(line => line.trim() && !line.trim().startsWith("--")))) {
          await db.prepare(statement).run();
        }
      }
      const actorId = "synthetic-ci-real-clamav-editor";
      await db.prepare(
        "INSERT INTO admin_users(id,email,is_active,created_at,updated_at) VALUES(?,?,1,'ci','ci')",
      ).bind(actorId,"synthetic-b312@example.test").run();
      sourceKey = "quarantine/v2/cms-main/" + signed.claim.uploadId;
      await db.prepare(`INSERT INTO media_r2_quarantine_uploads
        (id,scope_id,actor_user_id,idempotency_key,storage_key,mime_type,
        display_filename,byte_length,content_sha256,state,revision)
        VALUES(?,?,?,?,?,'image/png','real-av-ci-fixture.png',?,?,'QUARANTINED',1)`)
        .bind(signed.claim.uploadId, "cms-main", actorId, randomUUID(),
          sourceKey, source.byteLength, signed.claim.sourceSha256).run();
      await bucket.put(sourceKey, new Uint8Array(source));
      await bucket.put(signed.claim.derivativeKey, new Uint8Array(derivative));
    }, 60_000);

    afterAll(async () => { if (mf) await mf.dispose(); });

    it("verifies the ACTUAL Python HMAC from a clean image scanned twice by REAL ClamAV", async () => {
      const claim = signed.claim;
      const result = await verifyMediaScanClaim(signed, TEST_SECRET, {
        uploadId: claim.uploadId, scopeId: "cms-main", sourceRevision: 1,
        sourceSha256: await sha(source), sourceMime: "image/png",
      }, claim.signedAtMs);
      expect(result).toMatchObject({ok:true,claim:{verdict:"CLEAN",engine:"clamav"}});
    });

    it("rejects tampered private R2 derivative before storing ANY D1 proof", async () => {
      const tampered = new Uint8Array(derivative);
      tampered[12] ^= 0x01;
      await bucket.put(signed.claim.derivativeKey, tampered);
      const rejected = await storePrivateMediaScanEvidence(db, bucket, signed, TEST_SECRET, {
        provisioned: true, nowMs: signed.claim.signedAtMs,
      });
      expect(rejected).toMatchObject({ok:false,status:503,code:"PRIVATE_R2_READBACK_MISMATCH"});
      const evidence = await db.prepare("SELECT COUNT(*) AS n FROM media_r2_scan_evidence").first<{n:number}>();
      expect(evidence?.n).toBe(0);
      await bucket.put(signed.claim.derivativeKey, new Uint8Array(derivative));
    });

    it("commits the actual signed proof only privately after BOTH R2 SHA readbacks", async () => {
      const ok = await storePrivateMediaScanEvidence(db,bucket,signed,TEST_SECRET,{
        provisioned:true,nowMs:signed.claim.signedAtMs,
      });
      expect(ok).toMatchObject({ok:true,status:201,state:"SCAN_PASSED_PRIVATE",publicUrl:null});
      const upload = await db.prepare(`SELECT revision,state,scanner_attestation,derivative_key
        FROM media_r2_quarantine_uploads WHERE id=?`)
        .bind(signed.claim.uploadId)
        .first<{revision:number;state:string;scanner_attestation:null;derivative_key:null}>();
      expect(upload).toMatchObject({
        revision:2,state:"QUARANTINED",scanner_attestation:null,derivative_key:null,
      });
      const evidence = await db.prepare(`SELECT source_sha256,derivative_sha256,derivative_size,state
        FROM media_r2_scan_evidence WHERE source_upload_id=?`)
        .bind(signed.claim.uploadId)
        .first<{source_sha256:string;derivative_sha256:string;derivative_size:number;state:string}>();
      expect(evidence).toMatchObject({
        source_sha256:await sha(source),derivative_sha256:await sha(derivative),
        derivative_size:derivative.byteLength,state:"SCAN_PASSED_PRIVATE",
      });
      const audit = await db.prepare("SELECT COUNT(*) AS n FROM audit_logs WHERE entity_id=?")
        .bind(ok.ok ? ok.id : "")
        .first<{n:number}>();
      expect(audit?.n).toBe(1);
    });

    it("denies replay and nonce reuse without changing D1 source revision", async () => {
      const before = await db.prepare("SELECT revision FROM media_r2_quarantine_uploads WHERE id=?")
        .bind(signed.claim.uploadId).first<{revision:number}>();
      const replay = await storePrivateMediaScanEvidence(db,bucket,signed,TEST_SECRET,{
        provisioned:true,nowMs:signed.claim.signedAtMs,
      });
      expect(replay.ok).toBe(false);
      const after = await db.prepare("SELECT revision FROM media_r2_quarantine_uploads WHERE id=?")
        .bind(signed.claim.uploadId).first<{revision:number}>();
      expect(after?.revision).toBe(before?.revision);
      const evidence = await db.prepare("SELECT COUNT(*) AS n FROM media_r2_scan_evidence").first<{n:number}>();
      expect(evidence?.n).toBe(1);
    });

    it("deletes BOTH real scanner fixture objects on private retention and keeps no public URL", async () => {
      await db.prepare(`UPDATE media_r2_quarantine_uploads
        SET created_at=datetime('now','-8 days') WHERE id=?`)
        .bind(signed.claim.uploadId).run();
      const result = await cleanupExpiredPrivateMedia(db,bucket);
      expect(result.deleted).toBe(1);
      expect(await bucket.get?.(sourceKey)).toBeNull();
      expect(await bucket.get?.(signed.claim.derivativeKey)).toBeNull();
      const fk = await db.prepare("PRAGMA foreign_key_check").all();
      expect(fk.results).toHaveLength(0);
    });
  },
);
